{
  "avaliacoes": [
    {
      "id": "E8f5684c21de5e126",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A incompatibilidade química entre água de formação e água de injeção pode gerar precipitados; por isso, o texto indica a necessidade de testes de compatibilidade.",
          "trechos": [
            "E8f5684c21de5e126:0:690",
            "E8f5684c21de5e126:690:1390"
          ],
          "condicoes": [
            "mistura entre águas com composições iônicas distintas",
            "composição variável conforme poço e origem da água de injeção"
          ],
          "limites": [
            "fonte descreve composição e mecanismo geral, sem protocolo de teste detalhado",
            "não delimita aplicação específica a FPSO"
          ]
        },
        {
          "proposicao": "A presença de SO42- e CO32- com Ca2+, Ba2+ e Sr2+ pode levar à formação de incrustações, inclusive radioativas quando há Ra226.",
          "trechos": [
            "E8f5684c21de5e126:690:1390"
          ],
          "condicoes": [
            "presença simultânea dos íons citados na água produzida"
          ],
          "limites": [
            "não apresenta taxa, severidade nem critérios operacionais de mitigação"
          ]
        },
        {
          "proposicao": "A água produzida pode conter aditivos de processo como desemulsificantes, biocidas, inibidores de corrosão, antiespumantes, inibidores de incrustação e de hidratos, o que amplia o espectro de interações de compatibilidade a considerar.",
          "trechos": [
            "E8f5684c21de5e126:1390:2090",
            "E8f5684c21de5e126:2090:2401"
          ],
          "condicoes": [
            "uso de produtos químicos para melhorar produção ou tratar problemas do poço"
          ],
          "limites": [
            "enumera classes de químicos, mas não traz interações cruzadas específicas entre elas"
          ]
        }
      ]
    },
    {
      "id": "Ed5563d226562e3a6",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O desempenho do lubrificante depende de propriedades físico-químicas como viscosidade, estabilidade termo-oxidativa, estabilidade hidrolítica e solvência para aditivos.",
          "trechos": [
            "Ed5563d226562e3a6:697:1389"
          ],
          "condicoes": [
            "operação de sistemas mecânicos lubrificados"
          ],
          "limites": [
            "trecho trata de lubrificantes em geral, não de produtos químicos de processo em FPSO",
            "fronteira documental desconhecida"
          ]
        },
        {
          "proposicao": "Parâmetros como prevenção à corrosão, espuma e demulsificação podem ser melhorados com uso de aditivos.",
          "trechos": [
            "Ed5563d226562e3a6:1389:2088"
          ],
          "condicoes": [
            "formulação de óleos vegetais/lubrificantes com aditivos"
          ],
          "limites": [
            "afirmação geral de formulação, sem critérios de seleção ou compatibilidade de campo"
          ]
        },
        {
          "proposicao": "Compatibilidade com elastômeros é listada como característica crítica de desempenho e armazenamento/uso prolongado.",
          "trechos": [
            "Ed5563d226562e3a6:1389:2088"
          ],
          "condicoes": [
            "avaliação de características críticas de lubrificantes"
          ],
          "limites": [
            "não identifica elastômeros, fluidos específicos nem faixa de temperatura"
          ]
        }
      ]
    },
    {
      "id": "E58d006e86de91c89",
      "pertinente": false,
      "tipo": "indeterminado",
      "achados": []
    },
    {
      "id": "E1a0efb3d398ecb7e",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Em estudo de um campo na costa brasileira, modelagem seguida de análise laboratorial foi usada para avaliar compatibilidade com salmoura e calcular dosagem mínima efetiva de dois inibidores.",
          "trechos": [
            "E1a0efb3d398ecb7e:0:693"
          ],
          "condicoes": [
            "campo específico na costa brasileira",
            "uso de software de modelagem e posterior validação laboratorial"
          ],
          "limites": [
            "resultado restrito ao caso estudado",
            "não informa composição dos inibidores nem condições operacionais detalhadas"
          ]
        },
        {
          "proposicao": "Os dois inibidores avaliados foram reportados como compatíveis com a salmoura do campo e efetivos em baixas dosagens.",
          "trechos": [
            "E1a0efb3d398ecb7e:0:693"
          ],
          "condicoes": [
            "compatibilidade e efetividade avaliadas para a salmoura daquele campo"
          ],
          "limites": [
            "baixas dosagens não são quantificadas no trecho",
            "não permite extrapolar para outros campos, salmouras ou sistemas"
          ]
        },
        {
          "proposicao": "O estudo associa esses resultados ao tratamento preventivo de incrustação em poços.",
          "trechos": [
            "E1a0efb3d398ecb7e:0:693"
          ],
          "condicoes": [
            "uso preventivo em gerenciamento de incrustação"
          ],
          "limites": [
            "trata-se de conclusão do estudo/monografia, não de norma"
          ]
        }
      ]
    },
    {
      "id": "E517867b96ad1b12c",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A água produzida pode resultar da mistura de água de formação com água injetada em métodos de recuperação, contexto operacional ligado à ocorrência de incrustação.",
          "trechos": [
            "E517867b96ad1b12c:1382:2081",
            "E517867b96ad1b12c:2081:2300"
          ],
          "condicoes": [
            "reservatórios submetidos à injeção de água para recuperação"
          ],
          "limites": [
            "trecho introdutório, sem detalhar mecanismo de incompatibilidade nesta passagem"
          ]
        },
        {
          "proposicao": "O material referencia testes de compatibilidade de inibidores com cálcio da água de formação.",
          "trechos": [
            "E517867b96ad1b12c:0:697",
            "E517867b96ad1b12c:697:1382"
          ],
          "condicoes": [
            "avaliação de inibidores em estudo frente ao cálcio da água de formação"
          ],
          "limites": [
            "os resultados numéricos dos testes não aparecem nos trechos fornecidos",
            "trechos parecem ser índice/lista de tabelas, não descrição completa do estudo"
          ]
        },
        {
          "proposicao": "O material também referencia ensaio de encapsulamento de inibidor à base de fosfonato e testes de solubilidade, sugerindo avaliação de formulação além da simples eficiência anti-incrustação.",
          "trechos": [
            "E517867b96ad1b12c:697:1382"
          ],
          "condicoes": [
            "estudo experimental de materiais/portadores para inibidor"
          ],
          "limites": [
            "sem resultados, critérios de aceitação ou aplicabilidade operacional explícitos no trecho"
          ]
        }
      ]
    },
    {
      "id": "E66769e721f8cabf5",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A mistura de água do mar usada para injeção com água de formação pode causar incrustações por incompatibilidade química, especialmente precipitação de sais de sulfato.",
          "trechos": [
            "E66769e721f8cabf5:0:700"
          ],
          "condicoes": [
            "recuperação secundária em sistemas marinhos",
            "mistura entre água do mar e água de formação"
          ],
          "limites": [
            "não detalha janela operacional nem composição específica das águas"
          ]
        },
        {
          "proposicao": "Incrustações de carbonato são associadas a presença de CO2, composição química da água de formação e da rocha reservatório, além de variações de pressão e temperatura.",
          "trechos": [
            "E66769e721f8cabf5:700:1396"
          ],
          "condicoes": [
            "condições termodinâmicas e composicionais do meio"
          ],
          "limites": [
            "não apresenta pesos relativos dos fatores nem método de predição"
          ]
        },
        {
          "proposicao": "A escolha do inibidor deve considerar contaminantes da água, tendência de acúmulo de material orgânico, temperatura, pressão e custo global; a avaliação deve buscar condições próximas ao campo por testes de compatibilidade com salmouras sintéticas e eficiência estática ou dinâmica.",
          "trechos": [
            "E66769e721f8cabf5:1396:2092",
            "E66769e721f8cabf5:2092:2392"
          ],
          "condicoes": [
            "seleção e avaliação de inibidores de incrustação"
          ],
          "limites": [
            "é recomendação técnica geral, não norma",
            "fronteira documental desconhecida"
          ]
        }
      ]
    }
  ],
  "concluir": true,
